<section class="container form-layout page-section"><form method="post" action="<?= e(url('checkout',['id'=>$b['id']])) ?>" class="form-card" data-quote-form data-price="<?= $b['price_per_tonne'] ?>" data-origin="<?= e($b['governorate']) ?>" data-local-rate="<?= e(setting('shipping_local_per_tonne','35000')) ?>" data-other-rate="<?= e(setting('shipping_other_per_tonne','65000')) ?>" data-shipping-min="<?= e(setting('shipping_minimum','50000')) ?>" data-fee-bp="<?= e(setting('service_fee_bp','0')) ?>" data-fee-flat="<?= e(setting('service_fee_flat','0')) ?>" data-currency="<?= t('ج.م','EGP') ?>" data-available="<?= $available ?>"><?= csrf_field() ?><input type="hidden" name="action" value="order"><input type="hidden" name="batch_id" value="<?= $b['id'] ?>"><input type="hidden" name="expected_total" value="<?= number_format($total['total']/100,2,'.','') ?>"><h2><?= e(localized($b)) ?> <span class="badge"><?= t('درجة','Grade') ?> <?= e($b['grade']) ?></span></h2><p class="caption"><?= e($b['code']) ?> · <?= e($b['hub_'.lang()]) ?></p><div class="inspection-info"><span><?= t('الرطوبة المسجلة: ','Recorded moisture: ') ?><b><?= number_format((int)$b['moisture_bp']/100,2) ?>%</b></span><span><?= t('متاح: ','Available: ') ?><b><?= qty($available) ?> / <?= qty($available,'kg') ?></b></span></div><div class="note"><span><?= icon('shield') ?></span><p><?= t('المصدر والتحقق والسجلات الداخلية تديرهم حصاد. لن تظهر هوية البائع أو بيانات التواصل. تواصل مع حصاد لتأكيد المواصفات المطلوبة.','Hasad manages sourcing, verification and internal records. Seller identity and contact details remain private. Contact Hasad to confirm required specifications.') ?></p></div><div class="form-grid"><?php field(t('الكمية المطلوبة','Requested quantity'),'quantity','number',number_format($start/1000000,3,'.',''),'required min="0.001" max="1000" step="0.001" inputmode="decimal"');select_field(t('الوحدة','Unit'),'unit',['tonne'=>t('طن','Tonnes'),'kg'=>t('كيلوجرام','Kilograms')]); ?></div><p class="quantity-warning" data-quantity-warning hidden><?= t('الكمية المطلوبة تتجاوز المتاح أو أقل من كيلوجرام.','The requested quantity exceeds availability or is below one kilogram.') ?></p><?php field(t('اسم المصنع / الجهة','Factory / business name'),'organization','text','','required maxlength="190"'); ?><div class="form-grid"><label class="field"><span><?= t('محافظة التسليم','Delivery governorate') ?></span><select name="governorate" required><?= gov_options($defaultGov) ?></select></label><?php select_field(t('النقل','Transport'),'shipping_mode',['hasad'=>t('حصاد تنظم النقل — بتكلفة','Hasad arranges transport — charged'),'buyer'=>t('النقل من طرفي — شحن حصاد صفر','I arrange transport — zero Hasad shipping')]); ?></div><?php field(t('العنوان وملاحظة الموقع','Address and location note'),'destination','text','','required maxlength="500" autocomplete="street-address"'); ?><div class="quote-box" aria-live="polite"><div><span><?= t('تكلفة المادة','Material cost') ?></span><b data-quote-subtotal><?= money($total['subtotal']) ?></b></div><div><span><?= t('النقل','Transport') ?></span><b data-quote-shipping><?= money($total['shipping']) ?></b></div><div><span><?= t('رسوم الخدمة','Service fee') ?></span><b data-quote-fee><?= money($total['service_fee']) ?></b></div><div class="quote-total"><span><?= t('الإجمالي المستحق','Total due') ?></span><strong data-quote-total><?= money($total['total']) ?></strong></div></div><p class="caption"><?= t('الأسعار المقترحة للنقل قابلة للتعديل بواسطة الإدارة للطلبات الجديدة. العرض الحالي يتثبت عند الحجز.','Proposed transport rates can be changed by administrators for new orders. This quote is locked when you reserve.') ?></p><label class="consent"><input type="checkbox" name="accept" value="yes" required><span><?= t('راجعت الإجمالي والوزن ودرجة الفحص وأوافق على ','I reviewed the total, weight and physical grade and agree to the ') ?><a href="<?= e(url('terms')) ?>" target="_blank" rel="noopener"><?= t('شروط الطلب','order terms') ?></a>.</span></label><button type="submit" class="button button-green button-full" data-order-submit><?= t('احجز الكمية وانتقل للدفع','Reserve & continue to payment') ?><?= icon('arrow') ?></button><noscript><p class="note"><?= t('لتعديل الكمية والنقل ورؤية إجمالي جديد، فعّل JavaScript. يمكنك تقديم الطلب بالقيم الافتراضية الحالية.','Enable JavaScript to change quantity or transport and see an updated total. You can submit with the displayed default values.') ?></p></noscript></form><aside class="form-aside"><div class="aside-card"><span class="step-icon"><?= icon('shield') ?></span><h3><?= t('عرض محفوظ. وخطوات واضحة.','A saved quote. A clear next step.') ?></h3><p><?= t('بعد الحجز، يظهر حساب InstaPay أو المحفظة. حوّل المبلغ وسجّل مرجع التحويل. موظف حصاد يؤكد وصول الدفع قبل الشحن.','After reserving, you will see the InstaPay or wallet destination. Transfer the amount and submit its reference. Hasad confirms receipt before dispatch.') ?></p></div><div class="aside-card subtle"><h3><?= t('مهم قبل الاستخدام','Before using the material') ?></h3><p><?= t('الفحص الميداني ليس شهادة صلاحية للأعلاف. توافق المادة مع احتياجك واعتماد أي فحوص متخصصة مسؤولية المشتري.','Field inspection is not feed-safety certification. Buyers approve suitability for their requirements and any specialist testing.') ?></p></div></aside></section>
